Bash(powershell -NoProfile -NonInteractive -Command "
[System.IO.File]::WriteAllText\(
  ''C:\\Windows\\Temp\\fix_imports.js'',
  @''
const fs = require\(""fs""\);
const path = require\(""path""\);
const src = ""C:\\Projects\\House of Coco Content App\\Seocontentoptimizerapp-main\\Frontend\\src"";
const exts = new Set\(["".tsx"", "".ts"", "".jsx"", "".js""]\);
const fixed = [];
const pattern = /\(\(?:from|import|require\)\\s*[""'']\)\(@[^@""''\\/]+\\/[^@""'']+|[^@""''\\/][^@""'']*\)@\\d+\\.\\d+\\.\\d+/g;
function walk\(dir\) {
  for \(const entry of fs.readdirSync\(dir, { withFileTypes: true }\)\) {
    const full = path.join\(dir, entry.name\);
    if \(entry.isDirectory\(\)\) { walk\(full\); continue; }
    if \(exts.has\(path.extname\(entry.name\)\)\) {
      const original = fs.readFileSync\(full, ""utf8""\);
      const replaced = original.replace\(pattern, ""\\`$1\\`$2""\);
      if \(replaced !== original\) {
        fs.writeFileSync\(full, replaced, ""utf8""\);
        fixed.push\(entry.name\);
        console.log\(""Fixed: "" + entry.name\);
      }
    }
  }
}
walk\(src\);
console.log\(""---""\);
console.log\(""Total files fixed: "" + fixed.length\);
''@
\)
